-- Hex encoding for generated byte arrays: "0xNN" tokens, 16 per line.
-- Separators are written before each token so no trailing comma is emitted.

local PER_LINE = 16

local _byte_to_hex
local function byte_to_hex()
    if not _byte_to_hex then
        _byte_to_hex = {}
        for byte_value = 0, 255 do
            _byte_to_hex[string.char(byte_value)] = string.format("0x%02X", byte_value)
        end
    end
    return _byte_to_hex
end

-- Writes tokens for data, wrapping every PER_LINE bytes. column/started carry
-- line state so several buffers can be appended to the same line.
local function write_bytes(write, data, indent, column, started)
    local lookup = byte_to_hex()
    for index = 1, #data do
        if column == 0 then
            if started then
                write(",\n" .. indent)
            else
                write(indent)
                started = true
            end
        else
            write(", ")
        end
        write(lookup[data:sub(index, index)])
        column = column + 1
        if column == PER_LINE then
            column = 0
        end
    end
    return column, started
end

-- Builds hex-array text from raw bytes in memory.
function hex_body(data, indent)
    local parts = {}
    write_bytes(function(s) parts[#parts + 1] = s end, data, indent or "            ", 0, false)
    return table.concat(parts)
end
